struct FlashloanPaybackCpiBuilderInstruction<'a, 'b> {
    __program: &'b solana_account_info::AccountInfo<'a>,
    signer: Option<&'b solana_account_info::AccountInfo<'a>>,
    flashloan_admin: Option<&'b solana_account_info::AccountInfo<'a>>,
    signer_borrow_token_account: Option<&'b solana_account_info::AccountInfo<'a>>,
    mint: Option<&'b solana_account_info::AccountInfo<'a>>,
    flashloan_token_reserves_liquidity: Option<&'b solana_account_info::AccountInfo<'a>>,
    flashloan_borrow_position_on_liquidity: Option<&'b solana_account_info::AccountInfo<'a>>,
    rate_model: Option<&'b solana_account_info::AccountInfo<'a>>,
    vault: Option<&'b solana_account_info::AccountInfo<'a>>,
    liquidity: Option<&'b solana_account_info::AccountInfo<'a>>,
    liquidity_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    associated_token_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    system_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    instruction_sysvar: Option<&'b solana_account_info::AccountInfo<'a>>,
    amount: Option<u64>,
    /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
    __remaining_accounts: Vec<(&'b solana_account_info::AccountInfo<'a>, bool, bool)>,
}
